import re

_POS = {"first": 1, "second": 2, "third": 3, "fourth": 4, "fifth": 5,
        "sixth": 6, "seventh": 7, "eighth": 8}
_ALIAS = {"january": "jan", "february": "feb", "march": "mar",
          "september": "sept", "swedish": "swede", "british": "brit",
          "danish": "dane"}
_NODE_CAP = 600000
_BUDGET_MSG = "zebra-solver-v3-budget-exceeded"


def _norm(s):
    return re.sub(r"\s+", " ", s.lower().replace("-", " ")).strip()


def _keys_for(k):
    out = {k}
    for a, b in _ALIAS.items():
        if k == b:
            out.add(a)
        elif k == a:
            out.add(b)
    if len(k) > 5 and k.endswith("ing"):
        out.add(k[:-3])
    if len(k) > 3 and k.endswith("s"):
        out.add(k[:-1])
    if len(k) > 2:
        out.add(k + "s")
    return out


def _hdr(name):
    low = name.lower()
    tail = name.split("unique", 1)[1] if "unique" in low else name
    words = tail.strip(" :.").split()
    return (words[-1] if words else name)[:20]


def applies(view):
    q = (view or {}).get("question", "") or ""
    return ("## Clues:" in q) and bool(re.search(r"There are \d+ houses", q)) and "`" in q


def before_call(view, state):
    diag = []
    try:
        out = _run((view or {}).get("question", "") or "", diag)
    except Exception as e:
        return {"diagnostics": ["solver error: " + str(e)[:180]]}
    if out is None:
        d = diag[:5] or ["no note produced"]
        return {"diagnostics": d}
    return out


def _rel(kind, a, b):
    if kind == "left1":
        return b - a == 1
    if kind == "adj":
        return abs(a - b) == 1
    if kind == "lt":
        return a < b
    if kind == "gt":
        return a > b
    d = int(kind[1:])
    return abs(a - b) == d


def _run(q, diag):
    m = re.search(r"There are (\d+) houses", q)
    if not m:
        diag.append("house count not found")
        return None
    n = int(m.group(1))
    if not (2 <= n <= 7):
        diag.append("unsupported house count %d" % n)
        return None

    cats = []
    clues = []
    in_clues = False
    for ln in q.splitlines():
        s = ln.strip()
        if s.startswith("## Clues"):
            in_clues = True
            continue
        if in_clues:
            if s.startswith("#"):
                break
            cm = re.match(r"^(\d+)\.\s*(.+)$", s)
            if cm:
                clues.append(cm.group(2).strip())
            elif s and clues:
                clues[-1] += " " + s
        elif s.startswith("- ") and "`" in s and ":" in s:
            name = s[2:].split(":")[0].strip()
            vals = re.findall(r"`([^`]*)`", s)
            if name and vals:
                cats.append((name, vals))
    if not cats or not clues:
        diag.append("failed to parse categories (%d) or clues (%d)" % (len(cats), len(clues)))
        return None
    if len(cats) + 1 > 12:
        diag.append("too many categories: %d" % len(cats))
        return None

    keymap = {}
    for ci, (name, vals) in enumerate(cats):
        for v in vals:
            for kk in _keys_for(_norm(v)):
                keymap.setdefault(kk, []).append((ci, v))

    def scan(text):
        tl = _norm(text)
        used = [False] * len(tl)
        found = []
        amb = False
        for k in sorted(keymap, key=len, reverse=True):
            st = 0
            while True:
                i = tl.find(k, st)
                if i < 0:
                    break
                if not any(used[i:i + len(k)]):
                    for j in range(i, i + len(k)):
                        used[j] = True
                    lst = keymap[k]
                    found.append((i, lst))
                    if len(lst) > 1:
                        amb = True
                st = i + 1
        found.sort()
        return found, amb

    constraints = []
    unparsed = []
    for c in clues:
        low = _norm(c)
        found, amb = scan(c)
        vs = []
        seen = set()
        for i, lst in found:
            if len(lst) == 1:
                key = (lst[0][0], lst[0][1])
                if key not in seen:
                    seen.add(key)
                    vs.append(key)
        if amb:
            unparsed.append(c)
            continue
        pm = re.search(r"not in the (\w+) house", low)
        if pm and pm.group(1) in _POS:
            if len(vs) == 1:
                constraints.append(("notpos", vs[0], _POS[pm.group(1)]))
            else:
                unparsed.append(c)
            continue
        pm = re.search(r"\bin the (\w+) house\b", low)
        if pm and pm.group(1) in _POS:
            if len(vs) == 1:
                constraints.append(("pos", vs[0], _POS[pm.group(1)]))
            else:
                unparsed.append(c)
            continue
        if "directly left of" in low and len(vs) == 2:
            constraints.append(("pair", vs[0], vs[1], "left1"))
            continue
        if ("next to each other" in low or "are neighbors" in low) and len(vs) == 2:
            constraints.append(("pair", vs[0], vs[1], "adj"))
            continue
        bm = re.search(r"(one|two|three) houses? between", low)
        if bm and len(vs) == 2:
            d = {"one": 2, "two": 3, "three": 4}[bm.group(1)]
            constraints.append(("pair", vs[0], vs[1], "d%d" % d))
            continue
        if "somewhere to the left of" in low and len(vs) == 2:
            constraints.append(("pair", vs[0], vs[1], "lt"))
            continue
        if "somewhere to the right of" in low and len(vs) == 2:
            constraints.append(("pair", vs[0], vs[1], "gt"))
            continue
        if len(vs) == 2 and " is not " in low:
            constraints.append(("diff", vs[0], vs[1]))
            continue
        if len(vs) == 2 and " is " in low:
            constraints.append(("same", vs[0], vs[1]))
            continue
        unparsed.append(c)

    if unparsed:
        diag.append("unparsed clue: " + unparsed[0][:200])
        return None

    parent = {}

    def find(x):
        parent.setdefault(x, x)
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    contradiction = False
    for con in constraints:
        if con[0] == "same":
            a, b = con[1], con[2]
            if a[0] == b[0]:
                contradiction = True
            else:
                ra, rb = find(a), find(b)
                if ra != rb:
                    parent[ra] = rb
        elif con[0] == "diff":
            a, b = con[1], con[2]
            if a == b:
                contradiction = True

    pinned = {}
    notpos = {}
    pairs = []
    diffs = []
    for con in constraints:
        if con[0] == "pos":
            r = find(con[1])
            if pinned.get(r, con[2]) != con[2]:
                contradiction = True
            pinned[r] = con[2]
        elif con[0] == "notpos":
            notpos.setdefault(find(con[1]), set()).add(con[2])
        elif con[0] == "pair":
            pairs.append((find(con[1]), find(con[2]), con[3]))
        elif con[0] == "diff":
            ra, rb = find(con[1]), find(con[2])
            if ra == rb:
                contradiction = True
            else:
                diffs.append((ra, rb))

    if contradiction:
        diag.append("clue set is contradictory (same/diff conflict or conflicting pins)")
        return None

    reps = set()
    rep_cats = {}
    rep_members = {}
    for ci, (name, vals) in enumerate(cats):
        for v in vals:
            r = find((ci, v))
            reps.add(r)
            rep_cats.setdefault(r, set()).add(ci)
            rep_members.setdefault(r, []).append((ci, v))

    cons_by = {}
    for a, b, kind in pairs:
        if a == b:
            if not any(_rel(kind, p, p) for p in range(1, n + 1)):
                contradiction = True
            continue
        cons_by.setdefault(a, []).append((b, kind, True))
        cons_by.setdefault(b, []).append((a, kind, False))
    diff_by = {}
    for a, b in diffs:
        diff_by.setdefault(a, set()).add(b)
        diff_by.setdefault(b, set()).add(a)
    if contradiction:
        diag.append("clue set is contradictory")
        return None

    order = sorted(reps, key=lambda r: (0 if r in pinned else 1,
                                        -len(cons_by.get(r, ()))))
    sols = []
    nodes = [0]
    assign = {}
    occ = {}

    def bt(i):
        if len(sols) >= 2:
            return
        if i == len(order):
            sols.append(dict(assign))
            return
        r = order[i]
        for p in range(1, n + 1):
            nodes[0] += 1
            if nodes[0] > _NODE_CAP:
                raise RuntimeError(_BUDGET_MSG)
            if r in pinned and pinned[r] != p:
                continue
            if p in notpos.get(r, ()):
                continue
            clash = False
            for ci in rep_cats[r]:
                if (ci, p) in occ:
                    clash = True
                    break
            if clash:
                continue
            bad = False
            for other in diff_by.get(r, ()):
                if other in assign and assign[other] == p:
                    bad = True
                    break
            if bad:
                continue
            ok = True
            for other, kind, is_a in cons_by.get(r, ()):
                if other in assign:
                    pa = p if is_a else assign[other]
                    pb = assign[other] if is_a else p
                    if not _rel(kind, pa, pb):
                        ok = False
                        break
            if not ok:
                continue
            assign[r] = p
            marks = []
            for ci in rep_cats[r]:
                occ[(ci, p)] = r
                marks.append(ci)
            bt(i + 1)
            for ci in marks:
                del occ[(ci, p)]
            del assign[r]
            if len(sols) >= 2:
                return

    budget_hit = [False]
    try:
        bt(0)
    except RuntimeError as e:
        if str(e) != _BUDGET_MSG:
            raise
        budget_hit[0] = True
    if budget_hit[0]:
        diag.append("search budget exceeded (%d nodes)" % nodes[0])
        return None

    if len(sols) != 1:
        diag.append("solutions found: %d (need exactly 1)" % len(sols))
        return None

    sol = sols[0]
    headers = ["House"]
    used_h = set()
    for name, vals in cats:
        h = _hdr(name)
        while h.lower() in used_h:
            h = h + "2"
        used_h.add(h.lower())
        headers.append(h)
    rows = [headers]
    grid = {}
    for r, members in rep_members.items():
        p = sol[r]
        for ci, v in members:
            grid[(ci, p)] = v
    for hse in range(1, n + 1):
        row = [str(hse)]
        for ci in range(len(cats)):
            row.append(str(grid.get((ci, hse), "?"))[:40])
        rows.append(row)

    fact = ("Parsed all %d clues over %d categories; a backtracking search over "
            "position assignments found exactly one assignment consistent with "
            "the parsed clues, shown per house."
            % (len(clues), len(cats)))
    return {"facts": [fact[:200]], "warnings": [], "table": rows}
